{
  "name": "Massar Intel - Professeur Dashboard",
  "description": "Une application SaaS moderne pour les enseignants marocains, permettant de gérer les notes Massar, d'analyser les performances des élèves via l'IA Gemini et de visualiser les statistiques de classe.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Student {
  id: string;
  name: string;
  grade: number;
  participation: number;
  status: 'Pass' | 'Fail' | 'Warning';
  avatar: string;
}

export interface ClassInfo {
  id: string;
  name: string;
  count: number;
  average: number;
  successRate: number;
}

export type Language = 'fr' | 'ar';

export interface Translations {
  dashboard: string;
  classes: string;
  upload: string;
  studentName: string;
  grade: string;
  status: string;
  classAverage: string;
  successRate: string;
  aiInsights: string;
  dragDrop: string;
  selectClass: string;
  settings: string;
  logout: string;
}

import { GoogleGenAI } from "@google/genai";
import { Student } from "../types";

export const getGeminiInsights = async (students: Student[], lang: 'fr' | 'ar') => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const studentDataStr = students.map(s => `${s.name}: ${s.grade}`).join(', ');

  const prompt = lang === 'fr' 
    ? `Analyse ces notes d'élèves de la plateforme Massar et donne des conseils pédagogiques rapides pour l'enseignant. Sois concis et professionnel. Voici les données: ${studentDataStr}`
    : `حلل هذه النقاط لتلاميذ مسار وقدم نصائح تربوية سريعة للأستاذ. كن مختصراً ومهنياً. البيانات: ${studentDataStr}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: lang === 'fr' 
          ? "Tu es un expert en pédagogie marocaine, spécialisé dans l'analyse des données de la plateforme Massar."
          : "أنت خبير في البيداغوجيا المغربية، متخصص في تحليل بيانات منظومة مسار.",
        temperature: 0.7,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return lang === 'fr' ? "Impossible de générer les analyses IA pour le moment." : "عذراً، لا يمكن إنشاء التحليلات حالياً.";
  }
};

