              <button className="px-4 py-2 bg-blue-600 rounded-xl text-sm font-semibold text-white hover:bg-blue-700 shadow-md shadow-blue-200 transition-all">
                {lang === 'fr' ? 'Nouvelle Note' : 'نقطة جديدة'}
