                <div className="min-h-[200px] bg-white/10 backdrop-blur-sm rounded-xl p-4 text-sm leading-relaxed relative z-10 border border-white/10">
                  {loadingAi ? (
                    <div className="flex flex-col items-center justify-center h-48 gap-3">
                      <Loader2 className="animate-spin" size={24} />
