                    <div className="whitespace-pre-line text-blue-50">
                      {aiAnalysis || (lang === 'fr' ? "En attente de données..." : "في انتظار البيانات...")}
                    </div>
                  )}
                </div>

                <div className="mt-4 flex justify-end relative z-10">
                  <button 
                    onClick={() => generateInsights(students)}
                    className="text-xs bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg transition-all"
                  >
                    {lang === 'fr' ? 'Rafraîchir' : 'تحديث'}
                  </button>
                </div>
              </div>

              {/* Tips / Activity */}
              <div className="bg-white rounded-2xl p-6 border border-slate-100 shadow-sm">
                <h4 className="font-bold text-slate-800 mb-4">{lang === 'fr' ? 'Rappels' : 'تذكيرات'}</h4>
                <div className="space-y-4">
                  {[
                    { title: 'Saisie CC1', date: 'Avant le 15 Oct', color: 'bg-amber-500' },
                    { title: 'Conseil de classe', date: 'Le 20 Oct', color: 'bg-blue-500' },
                  ].map((item, i) => (
                    <div key={i} className="flex gap-4 items-start">
                      <div className={`w-2 h-2 rounded-full mt-2 ${item.color}`}></div>
                      <div>
                        <p className="text-sm font-semibold text-slate-700">{item.title}</p>
                        <p className="text-xs text-slate-400">{item.date}</p>
                      </div>
                    </div>
                  ))}
