                {lang === 'fr' ? 'Exporter' : 'تصدير'}
              </button>
              <button className="flex-1 sm:flex-none px-4 md:px-5 py-2.5 bg-blue-600 rounded-xl text-sm font-bold text-white hover:bg-blue-700 shadow-lg shadow-blue-200 hover:shadow-blue-300 transition-all">
                {lang === 'fr' ? 'Note' : 'نقطة'}
