                <div className="space-y-5">
                  {[
                    { title: 'Saisie CC1', date: 'Avant le 15 Oct', color: 'bg-amber-400', shadow: 'shadow-amber-100' },
                    { title: 'Conseil de classe', date: 'Le 20 Oct', color: 'bg-blue-400', shadow: 'shadow-blue-100' },
                  ].map((item, i) => (
                    <div key={i} className="flex gap-4 items-center group cursor-pointer p-2 -m-2 rounded-2xl hover:bg-slate-50 transition-all">
