                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{item.date}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

