interface StudentTableProps {
  students: Student[];
  t: Translations;
  lang: Language;
  onUpdateGrade: (id: string, grade: number) => void;
}

const StudentTable: React.FC<StudentTableProps> = ({ students, t, lang, onUpdateGrade }) => {
  const isAr = lang === 'ar';
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const handleGradeChange = (id: string, value: string) => {
    // Allow empty string for clearing, but update state with 0 or previous
    const num = value === '' ? 0 : parseFloat(value);
    if (!isNaN(num) && num >= 0 && num <= 20) {
      onUpdateGrade(id, num);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === 'Enter' || e.key === 'ArrowDown') {
      e.preventDefault();
      inputRefs.current[index + 1]?.focus();
      inputRefs.current[index + 1]?.select();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      inputRefs.current[index - 1]?.focus();
      inputRefs.current[index - 1]?.select();
    }
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    e.target.select();
  };

  return (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
      <div className="p-6 border-b border-slate-50 flex justify-between items-center">
        <h3 className="font-bold text-lg text-slate-800">Mes Classes</h3>
