          <thead className="bg-slate-50/50 text-slate-400 text-[10px] uppercase tracking-wider">
            <tr>
              <th className={`px-6 py-4 font-bold w-1/3 ${isAr ? 'text-right' : ''}`}>{t.studentName}</th>
              <th className={`px-6 py-4 font-bold w-1/4 ${isAr ? 'text-right' : ''}`}>{t.grade}</th>
              <th className={`px-6 py-4 font-bold w-1/4 ${isAr ? 'text-right' : ''}`}>{t.status}</th>
              <th className={`px-6 py-4 font-bold w-1/6 ${isAr ? 'text-right' : ''}`}>Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
