import React, { useRef } from 'react';
import { MoreHorizontal, Star } from 'lucide-react';
import { Student, Translations, Language } from '../types';

interface StudentTableProps {
  students: Student[];
  t: Translations;
  lang: Language;
  onUpdateGrade: (id: string, testIndex: number, grade: number) => void;
}

const StudentTable: React.FC<StudentTableProps> = ({ students, t, lang, onUpdateGrade }) => {
  const isAr = lang === 'ar';
  // 2D Ref array for [student_row][test_col]
  const inputRefs = useRef<(HTMLInputElement | null)[][]>([]);

  // Initialize refs array if needed
  if (inputRefs.current.length !== students.length) {
    inputRefs.current = Array(students.length).fill(null).map(() => Array(4).fill(null));
  }

  const handleGradeChange = (studentId: string, testIndex: number, value: string) => {
    const num = value === '' ? 0 : parseFloat(value);
    if (!isNaN(num) && num >= 0 && num <= 20) {
      onUpdateGrade(studentId, testIndex, num);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, row: number, col: number) => {
    if (e.key === 'Enter' || e.key === 'ArrowDown') {
      e.preventDefault();
      inputRefs.current[row + 1]?.[col]?.focus();
      inputRefs.current[row + 1]?.[col]?.select();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      inputRefs.current[row - 1]?.[col]?.focus();
      inputRefs.current[row - 1]?.[col]?.select();
    } else if (e.key === 'ArrowRight') {
      if (!isAr && inputRefs.current[row][col+1]) {
        inputRefs.current[row][col+1]?.focus();
        inputRefs.current[row][col+1]?.select();
      } else if (isAr && inputRefs.current[row][col-1]) {
        inputRefs.current[row][col-1]?.focus();
        inputRefs.current[row][col-1]?.select();
      }
    } else if (e.key === 'ArrowLeft') {
       if (!isAr && inputRefs.current[row][col-1]) {
        inputRefs.current[row][col-1]?.focus();
        inputRefs.current[row][col-1]?.select();
      } else if (isAr && inputRefs.current[row][col+1]) {
        inputRefs.current[row][col+1]?.focus();
        inputRefs.current[row][col+1]?.select();
      }
    }
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    e.target.select();
  };

  return (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
      <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-white sticky left-0">
        <h3 className="font-bold text-lg text-slate-800">Évaluations par Classe</h3>
        <button className="text-sm text-blue-600 font-bold hover:underline">Voir tout</button>
      </div>
      <div className="overflow-x-auto custom-scrollbar">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead className="bg-slate-50/50 text-slate-400 text-[10px] uppercase tracking-wider">
            <tr>
              <th className={`px-6 py-4 font-bold sticky left-0 bg-slate-50 z-10 w-[200px] ${isAr ? 'text-right' : ''}`}>{t.studentName}</th>
              {[1, 2, 3, 4].map(num => (
                <th key={num} className="px-4 py-4 font-bold text-center border-x border-slate-100/50 w-[80px]">Test {num}</th>
              ))}
              <th className={`px-6 py-4 font-bold text-center w-[120px] ${isAr ? 'text-right' : ''}`}>Moy.</th>
              <th className={`px-6 py-4 font-bold w-[120px] ${isAr ? 'text-right' : ''}`}>{t.status}</th>
              <th className={`px-6 py-4 font-bold w-[80px] ${isAr ? 'text-right' : ''}`}>Act.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {students.map((student, rowIndex) => {
              const studentAverage = (student.grades.reduce((a, b) => a + b, 0) / 4).toFixed(2);
              return (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 sticky left-0 bg-white group-hover:bg-slate-50/50 z-10">
                    <div className="flex flex-col">
                      <p className="font-bold text-slate-800 text-sm leading-none mb-1.5 truncate">{student.name}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">ID: {student.id.toUpperCase()}</p>
                    </div>
                  </td>
                  {student.grades.map((grade, colIndex) => (
                    <td key={colIndex} className="p-0 border-x border-slate-50 relative focus-within:bg-blue-50/30 focus-within:ring-2 focus-within:ring-inset focus-within:ring-blue-500 transition-all">
                      <div className="flex items-center justify-center h-full w-full py-4 px-2">
                        <input
                          ref={(el) => (inputRefs.current[rowIndex][colIndex] = el)}
                          type="number"
                          step="0.25"
                          min="0"
                          max="20"
                          value={grade || ''}
                          onFocus={handleFocus}
                          onChange={(e) => handleGradeChange(student.id, colIndex, e.target.value)}
                          onKeyDown={(e) => handleKeyDown(e, rowIndex, colIndex)}
                          className={`w-full bg-transparent text-base md:text-lg font-black outline-none transition-all text-center appearance-none cursor-cell ${
                            grade >= 10 ? 'text-slate-800' : 'text-rose-500'
                          }`}
                        />
                      </div>
                    </td>
                  ))}
                  <td className="px-6 py-4 text-center">
                    <span className={`text-sm font-black ${Number(studentAverage) >= 10 ? 'text-blue-600' : 'text-rose-600'}`}>
                      {studentAverage}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex px-3 py-1 rounded-lg text-[9px] font-bold uppercase tracking-wider ${
                      student.status === 'Pass' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' :
                      student.status === 'Warning' ? 'bg-amber-50 text-amber-600 border border-amber-100' :
                      'bg-rose-50 text-rose-600 border border-rose-100'
                    }`}>
                      {student.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button className="p-2 hover:bg-white border border-transparent hover:border-slate-200 rounded-xl text-slate-300 hover:text-slate-600 transition-all">
                      <MoreHorizontal size={16} />
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <style>{`
        input::-webkit-outer-spin-button,
        input::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
      `}</style>
    </div>
  );
};

export default StudentTable;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Sidebar from './components/Sidebar';
import StatsSection from './components/StatsSection';
import StudentTable from './components/StudentTable';
import AddNoteModal from './components/AddNoteModal';
import { Language, Student, ClassInfo } from './types';
import { TRANSLATIONS, MOCK_CLASSES, MOCK_STUDENTS } from './constants';
import { getGeminiInsights } from './services/geminiService';
import { Sparkles, Languages, Bell, Search, Loader2, Play, Menu as MenuIcon } from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('fr');
  const [classes, setClasses] = useState<ClassInfo[]>(MOCK_CLASSES);
  const [selectedClassId, setSelectedClassId] = useState(MOCK_CLASSES[0].id);
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAddNoteModalOpen, setIsAddNoteModalOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[lang];
  const isAr = lang === 'ar';
  const currentClass = classes.find(c => c.id === selectedClassId);

  const toggleLanguage = () => {
    setLang(prev => prev === 'fr' ? 'ar' : 'fr');
  };

  const generateInsights = useCallback(async (studentList: Student[]) => {
    setLoadingAi(true);
    const insights = await getGeminiInsights(studentList, lang);
    setAiAnalysis(insights || null);
    setLoadingAi(false);
  }, [lang]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.length) return;

    setIsImporting(true);
    // Simulate processing
    setTimeout(() => {
      const shuffled = [...MOCK_STUDENTS].sort(() => Math.random() - 0.5);
      setStudents(shuffled);
      setAiAnalysis(null);
      setIsImporting(false);
    }, 1500);
  };

  const triggerImport = () => {
    fileInputRef.current?.click();
  };

  const handleRenameClass = (id: string, newName: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, name: newName } : c));
  };

  const handleTogglePin = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isPinned: !c.isPinned } : c));
  };

  const handleToggleFavorite = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isFavorite: !c.isFavorite } : c));
  };

  const handleUpdateGrade = (studentId: string, testIndex: number, grade: number) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const updatedGrades = [...s.grades];
        updatedGrades[testIndex] = grade;

        // Calculate status based on average of the 4 tests
        const average = updatedGrades.reduce((a, b) => a + b, 0) / updatedGrades.length;
        let status: 'Pass' | 'Fail' | 'Warning' = 'Pass';
        if (average < 8) status = 'Fail';
        else if (average < 10) status = 'Warning';

        return { ...s, grades: updatedGrades, status };
      }
      return s;
    }));
    if (aiAnalysis) setAiAnalysis(null);
  };

  const handleSaveGradeFromModal = (studentId: string, grade: number) => {
    // For modal, we assume updating the first test for now or we could extend modal
    handleUpdateGrade(studentId, 0, grade);
    setIsAddNoteModalOpen(false);
  };

  const sortedClasses = [...classes].sort((a, b) => {
    if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
    if (a.isFavorite !== b.isFavorite) return a.isFavorite ? -1 : 1;
    return parseInt(a.id) - parseInt(b.id);
  });

  return (
    <div className={`flex min-h-screen bg-slate-50/50 ${isAr ? 'flex-row-reverse' : ''}`} dir={isAr ? 'rtl' : 'ltr'}>
      <input 
        type="file" 
        className="hidden" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".xlsx,.xls"
      />

      {isImporting && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 max-w-sm w-full">
            <div className="p-4 bg-blue-50 rounded-full">
              <Loader2 className="animate-spin text-blue-600" size={32} />
            </div>
            <div className="text-center">
              <h3 className="text-xl font-bold text-slate-800">Importation en cours...</h3>
              <p className="text-slate-500 text-sm mt-1">Traitement de votre fichier Excel Massar</p>
            </div>
          </div>
        </div>
      )}

      {isAddNoteModalOpen && (
        <AddNoteModal 
          students={students} 
          t={t} 
          lang={lang} 
          onClose={() => setIsAddNoteModalOpen(false)}
          onSave={handleSaveGradeFromModal}
        />
      )}

      <Sidebar 
        lang={lang} 
        t={t} 
        classes={sortedClasses} 
        selectedClassId={selectedClassId} 
        onSelectClass={setSelectedClassId}
        onImportClick={triggerImport}
        onRenameClass={handleRenameClass}
        onTogglePin={handleTogglePin}
        onToggleFavorite={handleToggleFavorite}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="h-16 bg-white border-b border-slate-200 px-4 md:px-8 flex items-center justify-between sticky top-0 z-30">
          <div className="flex items-center gap-4 flex-1">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all"
            >
              <MenuIcon size={24} />
            </button>
            <div className="relative max-w-md w-full hidden sm:block">
              <Search className={`absolute ${isAr ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-slate-400`} size={18} />
              <input 
                type="text" 
                placeholder="Rechercher un élève..." 
                className={`w-full bg-slate-100/80 border-none rounded-2xl py-2 ${isAr ? 'pr-11 pl-4' : 'pl-11 pr-4'} text-sm font-medium focus:ring-2 focus:ring-blue-500/20 outline-none transition-all`} 
              />
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
              onClick={toggleLanguage}
              className="flex items-center gap-2 px-3 py-2 hover:bg-slate-100 rounded-xl text-slate-600 transition-all font-bold text-xs uppercase tracking-wider"
            >
              <Languages size={18} className="text-blue-500" />
              <span className="hidden sm:inline">{lang === 'fr' ? 'العربية' : 'Français'}</span>
            </button>
            <div className="w-px h-6 bg-slate-200"></div>
            <button className="relative p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl transition-all group">
              <Bell size={20} />
              <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white group-hover:scale-110 transition-transform"></span>
            </button>
            <div className="flex items-center gap-3 ml-2 pl-2 cursor-pointer group">
              <img 
