                        />
                      </div>
                    </td>
                  ))}

                  <td className="px-4 md:px-6 py-4 text-center">
                    <span className={`text-xs md:text-sm font-black ${Number(studentAverage) >= 10 ? 'text-blue-600' : 'text-rose-600'}`}>
                      {studentAverage}
                    </span>
                  </td>

                  <td className="px-4 md:px-6 py-4 hidden sm:table-cell">
                    <span className={`inline-flex px-2 md:px-3 py-1 rounded-lg text-[8px] md:text-[9px] font-bold uppercase tracking-wider ${
                      student.status === 'Pass' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' :
                      student.status === 'Warning' ? 'bg-amber-50 text-amber-600 border border-amber-100' :
                      'bg-rose-50 text-rose-600 border border-rose-100'
                    }`}>
                      {student.status}
                    </span>
                  </td>

                  <td className="px-4 md:px-6 py-4 text-center">
                    <button className="p-2 hover:bg-white border border-transparent hover:border-slate-200 rounded-xl text-slate-300 hover:text-slate-600 transition-all">
                      <MoreHorizontal size={14} />
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-center md:hidden">
         <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Utilisez les flèches pour naviguer entre les élèves</p>
      </div>

      <style>{`
        input::-webkit-outer-spin-button,
        input::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
        @media (max-width: 768px) {
          .custom-scrollbar::-webkit-scrollbar {
            display: none;
          }
          .custom-scrollbar {
            -ms-overflow-style: none;
            scrollbar-width: none;
          }
        }
      `}</style>
    </div>
  );
};

