  const handleRemoveRule = (id: string) => {
    setRules(rules.filter(r => r.id !== id));
  };

  const handleUpdateRule = (id: string, field: keyof ObservationRule, value: any) => {
    setRules(rules.map(r => r.id === id ? { ...r, [field]: value } : r));
