import { GoogleGenAI } from "@google/genai";
import { Student } from "../types";

export const getGeminiInsights = async (students: Student[], lang: 'fr' | 'ar') => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const studentDataStr = students.map(s => `${s.name}: [${s.grades.join(', ')}]`).join('; ');

  const prompt = lang === 'fr' 
    ? `Analyse ces notes d'élèves de la plateforme Massar et donne des conseils pédagogiques rapides pour l'enseignant. Sois concis et professionnel. Voici les données: ${studentDataStr}`
    : `حلل هذه النقاط لتلاميذ مسار وقدم نصائح تربوية سريعة للأستاذ. كن مختصراً ومهنياً. البيانات: ${studentDataStr}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.0-flash-exp', // Updated to newer model for better reasoning
      contents: prompt,
      config: {
        systemInstruction: lang === 'fr' 
          ? "Tu es un expert en pédagogie marocaine, spécialisé dans l'analyse des données de la plateforme Massar."
          : "أنت خبير في البيداغوجيا المغربية، متخصص في تحليل بيانات منظومة مسار.",
        temperature: 0.7,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return lang === 'fr' ? "Impossible de générer les analyses IA pour le moment." : "عذراً، لا يمكن إنشاء التحليلات حالياً.";
  }
};

export const extractGradesFromAudio = async (base64Audio: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.0-flash-exp',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'audio/webm', // Assuming MediaRecorder provides webm or mp3
              data: base64Audio,
            },
          },
          {
            text: "Listen to the teacher reading grades. Extract a list of students and their grades. Return ONLY a JSON array with this structure: [{ \"name\": \"spoken_name\", \"grade\": number }]. If no grade is heard, ignore. Do not add markdown code blocks."
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
      }
    });

    const text = response.text || "[]";
    // Clean up if markdown is present despite instructions
    const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(jsonStr);
  } catch (error) {
    console.error("Gemini Audio Error:", error);
    return [];
  }
};

// Calculates the Levenshtein distance between two strings
export const getLevenshteinDistance = (a: string, b: string): number => {
  const matrix = [];
  const normalizedA = a.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
  const normalizedB = b.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

  for (let i = 0; i <= normalizedB.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= normalizedA.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= normalizedB.length; i++) {
    for (let j = 1; j <= normalizedA.length; j++) {
      if (normalizedB.charAt(i - 1) === normalizedA.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          Math.min(
            matrix[i][j - 1] + 1,   // insertion
            matrix[i - 1][j] + 1    // deletion
          )
        );
      }
    }
  }

  return matrix[normalizedB.length][normalizedA.length];
};

// Finds the best match from a list of students
export const findBestMatch = (
  spokenName: string, 
  students: { id: string; name: string }[]
): { studentId: string; name: string; confidence: number } | null => {

  let bestMatch = null;
  let minDistance = Infinity;

  students.forEach(student => {
    // Check against full name
    const distanceFull = getLevenshteinDistance(spokenName, student.name);

    // Check against first name only (teacher might say "Amine" instead of "Amine El Alami")
    const firstName = student.name.split(' ')[0];
    const distanceFirst = getLevenshteinDistance(spokenName, firstName);

    // Take the better of the two
    const distance = Math.min(distanceFull, distanceFirst);

    if (distance < minDistance) {
      minDistance = distance;
      bestMatch = student;
    }
  });

  // Tolerance threshold: 
  // Allow slightly more error for longer names, strict for short names.
  // A distance of 3 or less is usually a good fuzzy match for names.
  if (minDistance <= 4) {
    return {
      studentId: bestMatch!.id,
      name: bestMatch!.name,
      confidence: 1 - (minDistance / 10) // Rough confidence score
    };
  }

  return null;
};

import React, { useState, useRef, useEffect } from 'react';
import { X, Mic, Square, Loader2, Check, AlertCircle, RefreshCw, Send } from 'lucide-react';
import { Translations, Language, Student } from '../types';
import { extractGradesFromAudio } from '../services/geminiService';
import { findBestMatch } from '../utils/fuzzyMatch';

interface VoiceEntryModalProps {
  students: Student[];
  t: Translations;
  lang: Language;
  onClose: () => void;
  onSave: (updates: { studentId: string; grade: number }[]) => void;
}

type RecordingState = 'idle' | 'recording' | 'processing' | 'review';

interface MatchedGrade {
  spokenName: string;
  grade: number;
  studentId?: string;
  matchedName?: string;
  error?: boolean;
}

const VoiceEntryModal: React.FC<VoiceEntryModalProps> = ({ students, t, lang, onClose, onSave }) => {
  const [state, setState] = useState<RecordingState>('idle');
  const [results, setResults] = useState<MatchedGrade[]>([]);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const isAr = lang === 'ar';

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = handleProcessing;
      mediaRecorder.start();
      setState('recording');
    } catch (err) {
      console.error("Error accessing microphone:", err);
      alert("Microphone access denied or not available.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && state === 'recording') {
      mediaRecorderRef.current.stop();
      // Stop all tracks
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        // Remove data url prefix (e.g. "data:audio/webm;base64,")
        const base64 = base64String.split(',')[1];
        resolve(base64);
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const handleProcessing = async () => {
    setState('processing');
    const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });

    try {
      const base64Audio = await blobToBase64(audioBlob);
      const extractedData = await extractGradesFromAudio(base64Audio);

      const matchedData: MatchedGrade[] = extractedData.map((item: any) => {
        const match = findBestMatch(item.name, students);
        if (match) {
          return {
            spokenName: item.name,
            grade: item.grade,
            studentId: match.studentId,
            matchedName: match.name
          };
        } else {
          return {
            spokenName: item.name,
            grade: item.grade,
            error: true
          };
        }
      });

      setResults(matchedData);
      setState('review');
    } catch (error) {
      console.error("Processing failed", error);
      setState('idle');
    }
  };

  const handleApply = () => {
    const validUpdates = results
      .filter(r => r.studentId && !r.error)
      .map(r => ({ studentId: r.studentId!, grade: r.grade }));

    onSave(validUpdates);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      />

      <div className={`relative bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh] ${isAr ? 'rtl' : 'ltr'}`}>
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <Mic className="text-blue-600" size={20} />
            {t.voiceEntry}
          </h3>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 hover:bg-white rounded-xl transition-all"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8 flex flex-col items-center flex-1 overflow-y-auto custom-scrollbar">

          {state === 'idle' && (
            <div className="text-center space-y-6 py-6">
              <div className="p-6 bg-blue-50 rounded-full inline-flex mb-2">
                <Mic size={48} className="text-blue-600" />
              </div>
              <div>
                <p className="text-lg font-bold text-slate-800 mb-2">{t.voiceInstructions}</p>
                <p className="text-slate-400 text-sm">Gemini AI (Flash 2.0) analysera votre voix.</p>
              </div>
              <button 
                onClick={startRecording}
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold text-lg hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-3"
              >
                <Mic size={24} />
                {t.startRecording}
              </button>
            </div>
          )}

          {state === 'recording' && (
            <div className="text-center space-y-8 py-6 w-full">
              <div className="relative inline-flex">
                <div className="absolute inset-0 bg-rose-500 rounded-full animate-ping opacity-20"></div>
                <div className="p-8 bg-rose-50 rounded-full relative z-10 border-4 border-rose-100">
                  <Mic size={48} className="text-rose-600 animate-pulse" />
                </div>
              </div>
              <div>
                <p className="text-xl font-black text-slate-800 mb-1">Enregistrement...</p>
                <p className="text-slate-400 font-medium">Lisez les notes clairement</p>
              </div>
              <button 
                onClick={stopRecording}
                className="w-full py-4 bg-rose-600 text-white rounded-2xl font-bold text-lg hover:bg-rose-700 shadow-lg shadow-rose-200 transition-all flex items-center justify-center gap-3"
              >
                <Square size={24} fill="currentColor" />
                {t.stopRecording}
              </button>
            </div>
          )}

          {state === 'processing' && (
            <div className="text-center space-y-6 py-12">
              <Loader2 size={48} className="text-blue-600 animate-spin mx-auto" />
              <p className="text-lg font-bold text-slate-600 animate-pulse">{t.processing}</p>
            </div>
          )}

          {state === 'review' && (
            <div className="w-full space-y-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-bold text-slate-700">{t.confirmGrades}</h4>
                <span className="text-xs font-bold bg-blue-100 text-blue-700 px-2 py-1 rounded-md">
                  {results.filter(r => !r.error).length} détectés
                </span>
              </div>

              <div className="space-y-2">
                {results.length === 0 ? (
                  <p className="text-center text-slate-400 py-4 italic">{t.noMatchFound}</p>
                ) : (
                  results.map((res, idx) => (
                    <div 
                      key={idx} 
                      className={`p-3 rounded-xl border flex items-center justify-between ${
                        res.error 
                          ? 'bg-red-50 border-red-100' 
                          : 'bg-green-50 border-green-100'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        {res.error ? (
                          <AlertCircle size={18} className="text-red-400" />
                        ) : (
                          <Check size={18} className="text-green-600" />
                        )}
                        <div>
                          <p className={`text-sm font-bold ${res.error ? 'text-red-700' : 'text-slate-800'}`}>
                            {res.matchedName || `"${res.spokenName}"`}
                          </p>
                          {res.error && (
                            <p className="text-[10px] text-red-400 uppercase font-bold">Inconnu</p>
                          )}
                        </div>
                      </div>
                      <div className="font-black text-lg text-slate-800 bg-white px-3 py-1 rounded-lg shadow-sm border border-slate-100">
                        {res.grade}
                      </div>
                    </div>
                  ))
                )}
              </div>

              <div className="flex gap-3 mt-6 pt-4 border-t border-slate-50">
                <button 
                  onClick={() => { setResults([]); setState('idle'); }}
                  className="flex-1 py-3 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 transition-all flex items-center justify-center gap-2"
                >
                  <RefreshCw size={18} />
                  {t.retry}
                </button>
                <button 
                  onClick={handleApply}
                  disabled={results.filter(r => !r.error).length === 0}
                  className="flex-2 px-8 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2"
                >
                  <Send size={18} />
                  {t.apply}
                </button>
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

export default VoiceEntryModal;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Sidebar from './components/Sidebar';
import StatsSection from './components/StatsSection';
import StudentTable from './components/StudentTable';
import AddNoteModal from './components/AddNoteModal';
import ObservationRulesModal from './components/ObservationRulesModal';
import VoiceEntryModal from './components/VoiceEntryModal';
import { Language, Student, ClassInfo, ObservationRule } from './types';
import { TRANSLATIONS, MOCK_CLASSES, MOCK_STUDENTS } from './constants';
import { getGeminiInsights } from './services/geminiService';
import { Sparkles, Languages, Bell, Search, Loader2, Play, Menu as MenuIcon, Mic } from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('fr');
  const [classes, setClasses] = useState<ClassInfo[]>(MOCK_CLASSES);
  const [selectedClassId, setSelectedClassId] = useState(MOCK_CLASSES[0].id);
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAddNoteModalOpen, setIsAddNoteModalOpen] = useState(false);
  const [isRulesModalOpen, setIsRulesModalOpen] = useState(false);
  const [isVoiceModalOpen, setIsVoiceModalOpen] = useState(false);

  const [observationRules, setObservationRules] = useState<ObservationRule[]>([
    { id: '1', min: 18, max: 20, template: "Excellent travail [nom], continue ainsi!" },
    { id: '2', min: 14, max: 17.99, template: "Très bon semestre [nom], très sérieux." },
    { id: '3', min: 10, max: 13.99, template: "Passable, [nom] doit redoubler d'efforts." },
    { id: '4', min: 0, max: 9.99, template: "Résultats insuffisants, [nom] doit se ressaisir." },
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[lang];
  const isAr = lang === 'ar';
  const currentClass = classes.find(c => c.id === selectedClassId);

  const toggleLanguage = () => {
    setLang(prev => prev === 'fr' ? 'ar' : 'fr');
  };

  const generateInsights = useCallback(async (studentList: Student[]) => {
    setLoadingAi(true);
    const insights = await getGeminiInsights(studentList, lang);
    setAiAnalysis(insights || null);
    setLoadingAi(false);
  }, [lang]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.length) return;

    setIsImporting(true);
    // Simulate processing
    setTimeout(() => {
      const shuffled = [...MOCK_STUDENTS].sort(() => Math.random() - 0.5);
      setStudents(shuffled);
      setAiAnalysis(null);
      setIsImporting(false);
    }, 1500);
  };

  const triggerImport = () => {
    fileInputRef.current?.click();
  };

  const handleRenameClass = (id: string, newName: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, name: newName } : c));
  };

  const handleTogglePin = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isPinned: !c.isPinned } : c));
  };

  const handleToggleFavorite = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isFavorite: !c.isFavorite } : c));
  };

  const handleUpdateGrade = (studentId: string, testIndex: number, grade: number) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const updatedGrades = [...s.grades];
        updatedGrades[testIndex] = grade;

        // Calculate status based on average of the 4 tests
        const average = updatedGrades.reduce((a, b) => a + b, 0) / updatedGrades.length;
        let status: 'Pass' | 'Fail' | 'Warning' = 'Pass';
        if (average < 8) status = 'Fail';
        else if (average < 10) status = 'Warning';

        return { ...s, grades: updatedGrades, status };
      }
      return s;
    }));
    if (aiAnalysis) setAiAnalysis(null);
  };

  const handleSaveGradeFromModal = (studentId: string, grade: number) => {
    handleUpdateGrade(studentId, 0, grade);
    setIsAddNoteModalOpen(false);
  };

  const handleBatchUpdateFromVoice = (updates: { studentId: string; grade: number }[]) => {
    setStudents(prev => prev.map(s => {
      const update = updates.find(u => u.studentId === s.id);
      if (update) {
        const updatedGrades = [...s.grades];
        // Updating the first test by default for this example, or push to empty slot
        updatedGrades[0] = update.grade;

        const average = updatedGrades.reduce((a, b) => a + b, 0) / updatedGrades.length;
        let status: 'Pass' | 'Fail' | 'Warning' = 'Pass';
        if (average < 8) status = 'Fail';
        else if (average < 10) status = 'Warning';

        return { ...s, grades: updatedGrades, status };
      }
      return s;
    }));
    if (aiAnalysis) setAiAnalysis(null);
  };

  const handleSaveRules = (newRules: ObservationRule[]) => {
    setObservationRules(newRules);
    setIsRulesModalOpen(false);
  };

  const sortedClasses = [...classes].sort((a, b) => {
    if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
    if (a.isFavorite !== b.isFavorite) return a.isFavorite ? -1 : 1;
    return parseInt(a.id) - parseInt(b.id);
  });

  return (
    <div className={`flex min-h-screen bg-slate-50/50 ${isAr ? 'flex-row-reverse' : ''}`} dir={isAr ? 'rtl' : 'ltr'}>
      <input 
        type="file" 
        className="hidden" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".xlsx,.xls"
      />

      {isImporting && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 max-w-sm w-full">
            <div className="p-4 bg-blue-50 rounded-full">
              <Loader2 className="animate-spin text-blue-600" size={32} />
            </div>
            <div className="text-center">
              <h3 className="text-xl font-bold text-slate-800">Importation en cours...</h3>
              <p className="text-slate-500 text-sm mt-1">Traitement de votre fichier Excel Massar</p>
            </div>
          </div>
        </div>
      )}

      {isAddNoteModalOpen && (
        <AddNoteModal 
          students={students} 
          t={t} 
          lang={lang} 
          onClose={() => setIsAddNoteModalOpen(false)}
          onSave={handleSaveGradeFromModal}
        />
      )}

      {isVoiceModalOpen && (
        <VoiceEntryModal
          students={students}
          t={t}
          lang={lang}
          onClose={() => setIsVoiceModalOpen(false)}
          onSave={handleBatchUpdateFromVoice}
        />
      )}

      {isRulesModalOpen && (
        <ObservationRulesModal 
          rules={observationRules}
          lang={lang}
          onClose={() => setIsRulesModalOpen(false)}
          onSave={handleSaveRules}
        />
      )}

      <Sidebar 
        lang={lang} 
        t={t} 
        classes={sortedClasses} 
        selectedClassId={selectedClassId} 
        onSelectClass={setSelectedClassId}
        onImportClick={triggerImport}
        onRenameClass={handleRenameClass}
        onTogglePin={handleTogglePin}
        onToggleFavorite={handleToggleFavorite}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="h-16 bg-white border-b border-slate-200 px-4 md:px-8 flex items-center justify-between sticky top-0 z-30">
          <div className="flex items-center gap-4 flex-1">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all"
            >
              <MenuIcon size={24} />
            </button>
            <div className="relative max-w-md w-full hidden sm:block">
              <Search className={`absolute ${isAr ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-slate-400`} size={18} />
              <input 
                type="text" 
                placeholder="Rechercher un élève..." 
                className={`w-full bg-slate-100/80 border-none rounded-2xl py-2 ${isAr ? 'pr-11 pl-4' : 'pl-11 pr-4'} text-sm font-medium focus:ring-2 focus:ring-blue-500/20 outline-none transition-all`} 
              />
