  classes: ClassInfo[];
  selectedClassId: string;
  onSelectClass: (id: string) => void;
  onDashboardClick: () => void;
  onImportClick: () => void;
  onRenameClass: (id: string, newName: string) => void;
  onTogglePin: (id: string) => void;
  onToggleFavorite: (id: string) => void;
  isOpen?: boolean;
  onClose?: () => void;
  currentView?: 'dashboard' | 'class';
}

const Sidebar: React.FC<SidebarProps> = ({ 
  lang, t, classes, selectedClassId, onSelectClass, onDashboardClick, onImportClick,
  onRenameClass, onTogglePin, onToggleFavorite, isOpen, onClose, currentView = 'dashboard'
}) => {
  const isAr = lang === 'ar';
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  const handleStartRename = (e: React.MouseEvent, cls: ClassInfo) => {
    e.stopPropagation();
    setEditingId(cls.id);
    setEditValue(cls.name);
  };

  const handleSaveRename = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (editValue.trim()) {
      onRenameClass(id, editValue.trim());
    }
    setEditingId(null);
  };

  const sidebarClasses = `
    w-72 bg-white border-r border-slate-200 flex flex-col h-screen transition-transform duration-300 ease-in-out z-50
    fixed inset-y-0
    ${isAr ? 'right-0 border-l border-r-0' : 'left-0'}
    ${isOpen ? 'translate-x-0' : isAr ? 'translate-x-full' : '-translate-x-full'}
    lg:translate-x-0 lg:sticky lg:top-0 lg:z-20
  `;

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      <div className={sidebarClasses}>
        <div className="p-6 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2.5 rounded-xl shadow-lg shadow-blue-100">
              <GraduationCap className="text-white w-6 h-6" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">Massar Intel</h1>
          </div>
          <button 
            onClick={onClose}
            className="lg:hidden p-2 text-slate-400 hover:bg-slate-50 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 px-4 py-4 space-y-1 overflow-y-auto custom-scrollbar">
          <div className="mb-8">
            <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-[0.1em] mb-3">Main</p>
            <button 
              onClick={() => {
                onDashboardClick();
                if (window.innerWidth < 1024) onClose?.();
              }}
              className={`flex items-center gap-3 w-full px-4 py-3 rounded-xl font-semibold transition-all shadow-sm mb-2 ${
                currentView === 'dashboard'
                  ? 'text-blue-600 bg-blue-50/80 border border-blue-100/50'
                  : 'text-slate-600 hover:bg-slate-50 border border-transparent'
              }`}
            >
              <LayoutDashboard size={20} strokeWidth={2.5} />
              <span>{t.dashboard}</span>
            </button>

            <button 
              onClick={onImportClick}
              className="flex items-center gap-3 w-full px-4 py-3 text-slate-600 hover:bg-slate-50 rounded-xl font-medium transition-all group"
            >
              <div className="p-1 bg-slate-100 group-hover:bg-blue-100 rounded text-slate-400 group-hover:text-blue-600 transition-colors">
                <FileUp size={16} />
              </div>
              <span>{t.importAction}</span>
            </button>
          </div>

          <div>
            <div className="flex justify-between items-center px-3 mb-3">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.1em]">{t.classes}</p>
              <PlusCircle size={14} className="text-slate-300 cursor-pointer hover:text-blue-500 transition-colors" />
            </div>
            <div className="space-y-1">
              {classes.map((cls) => (
                <div 
                  key={cls.id}
                  onClick={() => {
                    onSelectClass(cls.id);
                    if (window.innerWidth < 1024) onClose?.();
                  }}
                  className={`group flex flex-col w-full p-2 rounded-xl transition-all cursor-pointer ${
                    currentView === 'class' && selectedClassId === cls.id 
                      ? 'bg-slate-100/80' 
                      : 'hover:bg-slate-50'
                  }`}
                >
                  <div className="flex items-center justify-between px-2 py-1.5">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <Users size={18} className={currentView === 'class' && selectedClassId === cls.id ? 'text-blue-600' : 'text-slate-400'} />
                      {editingId === cls.id ? (
                        <div className="flex items-center gap-1 w-full" onClick={e => e.stopPropagation()}>
                          <input 
                            autoFocus
                            value={editValue}
                            onChange={e => setEditValue(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && handleSaveRename(e as any, cls.id)}
                            className="w-full text-sm font-bold bg-white border border-blue-200 rounded px-1 outline-none focus:ring-2 focus:ring-blue-100"
                          />
                          <button onClick={(e) => handleSaveRename(e, cls.id)} className="p-1 bg-blue-600 text-white rounded shadow-sm">
                            <Check size={12} />
                          </button>
                        </div>
                      ) : (
                        <span className={`truncate text-sm ${currentView === 'class' && selectedClassId === cls.id ? 'font-bold text-slate-900' : 'text-slate-500 font-medium'}`}>
                          {cls.name}
                        </span>
                      )}
                    </div>

                    {editingId !== cls.id && (
                      <div className="flex items-center gap-1 ml-2">
                        <div className="flex items-center opacity-0 lg:group-hover:opacity-100 transition-opacity">
                           <button 
                            onClick={(e) => handleStartRename(e, cls)}
                            className="p-1 text-slate-400 hover:text-blue-500 hover:bg-white rounded transition-all"
                          >
                            <Pencil size={12} />
                          </button>
                          <button 
                            onClick={(e) => { e.stopPropagation(); onTogglePin(cls.id); }}
                            className={`p-1 transition-all rounded ${cls.isPinned ? 'text-blue-500 bg-white' : 'text-slate-400 hover:text-blue-500 hover:bg-white'}`}
                          >
                            <Pin size={12} className={cls.isPinned ? 'fill-blue-500' : ''} />
                          </button>
                          <button 
                            onClick={(e) => { e.stopPropagation(); onToggleFavorite(cls.id); }}
                            className={`p-1 transition-all rounded ${cls.isFavorite ? 'text-amber-500 bg-white' : 'text-slate-400 hover:text-amber-500 hover:bg-white'}`}
                          >
                            <Star size={12} className={cls.isFavorite ? 'fill-amber-500' : ''} />
                          </button>
                        </div>

                        {!cls.isPinned && !cls.isFavorite && (
                           <span className={`text-[10px] px-1.5 py-0.5 rounded-md lg:group-hover:hidden ${
                            currentView === 'class' && selectedClassId === cls.id ? 'bg-white text-slate-600 shadow-sm' : 'bg-slate-50 text-slate-400'
                          }`}>
                            {cls.count}
                          </span>
                        )}

                        <div className="flex gap-0.5 lg:group-hover:hidden">
                          {cls.isPinned && <Pin size={10} className="text-blue-500 fill-blue-500" />}
                          {cls.isFavorite && <Star size={10} className="text-amber-500 fill-amber-500" />}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </nav>

        <div className="p-4 border-t border-slate-100 space-y-1 mt-auto flex-shrink-0">
          <button className="flex items-center gap-3 w-full px-4 py-3 text-slate-500 hover:bg-slate-50 rounded-xl transition-all font-medium">
            <Settings size={20} />
            <span>{t.settings}</span>
          </button>
          <button className="flex items-center gap-3 w-full px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-all font-medium">
            <LogOut size={20} />
            <span>{t.logout}</span>
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Sidebar from './components/Sidebar';
import StatsSection from './components/StatsSection';
import StudentTable from './components/StudentTable';
import AddNoteModal from './components/AddNoteModal';
import ObservationRulesModal from './components/ObservationRulesModal';
import VoiceEntryModal from './components/VoiceEntryModal';
import DashboardHome from './components/DashboardHome';
import { Language, Student, ClassInfo, ObservationRule } from './types';
import { TRANSLATIONS, MOCK_CLASSES, MOCK_STUDENTS } from './constants';
import { getGeminiInsights } from './services/geminiService';
import { Sparkles, Languages, Bell, Search, Loader2, Play, Menu as MenuIcon, Mic } from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('fr');
  const [currentView, setCurrentView] = useState<'dashboard' | 'class'>('dashboard');
  const [classes, setClasses] = useState<ClassInfo[]>(MOCK_CLASSES);
  const [selectedClassId, setSelectedClassId] = useState(MOCK_CLASSES[0].id);
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAddNoteModalOpen, setIsAddNoteModalOpen] = useState(false);
  const [isRulesModalOpen, setIsRulesModalOpen] = useState(false);
  const [isVoiceModalOpen, setIsVoiceModalOpen] = useState(false);

  const [observationRules, setObservationRules] = useState<ObservationRule[]>([
    { id: '1', min: 18, max: 20, template: "Excellent travail [nom], continue ainsi!" },
    { id: '2', min: 14, max: 17.99, template: "Très bon semestre [nom], très sérieux." },
    { id: '3', min: 10, max: 13.99, template: "Passable, [nom] doit redoubler d'efforts." },
    { id: '4', min: 0, max: 9.99, template: "Résultats insuffisants, [nom] doit se ressaisir." },
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[lang];
  const isAr = lang === 'ar';
  const currentClass = classes.find(c => c.id === selectedClassId);

  const toggleLanguage = () => {
    setLang(prev => prev === 'fr' ? 'ar' : 'fr');
  };

  const generateInsights = useCallback(async (studentList: Student[]) => {
    setLoadingAi(true);
    const insights = await getGeminiInsights(studentList, lang);
    setAiAnalysis(insights || null);
    setLoadingAi(false);
  }, [lang]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.length) return;

    setIsImporting(true);
    // Simulate processing
    setTimeout(() => {
      const shuffled = [...MOCK_STUDENTS].sort(() => Math.random() - 0.5);
      setStudents(shuffled);
      setAiAnalysis(null);
      setIsImporting(false);
    }, 1500);
  };

  const triggerImport = () => {
    fileInputRef.current?.click();
  };

  const handleRenameClass = (id: string, newName: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, name: newName } : c));
  };

  const handleTogglePin = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isPinned: !c.isPinned } : c));
  };

  const handleToggleFavorite = (id: string) => {
    setClasses(prev => prev.map(c => c.id === id ? { ...c, isFavorite: !c.isFavorite } : c));
  };

  const handleUpdateGrade = (studentId: string, testIndex: number, grade: number) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const updatedGrades = [...s.grades];
        updatedGrades[testIndex] = grade;

        // Calculate status based on average of the 4 tests
        const average = updatedGrades.reduce((a, b) => a + b, 0) / updatedGrades.length;
        let status: 'Pass' | 'Fail' | 'Warning' = 'Pass';
        if (average < 8) status = 'Fail';
        else if (average < 10) status = 'Warning';

        return { ...s, grades: updatedGrades, status };
      }
      return s;
    }));
    if (aiAnalysis) setAiAnalysis(null);
  };

  const handleSaveGradeFromModal = (studentId: string, grade: number) => {
    handleUpdateGrade(studentId, 0, grade);
    setIsAddNoteModalOpen(false);
  };

  const handleBatchUpdateFromVoice = (updates: { studentId: string; grade: number }[], testIndex: number) => {
    setStudents(prev => prev.map(s => {
      const update = updates.find(u => u.studentId === s.id);
      if (update) {
        const updatedGrades = [...s.grades];
        // Ensure array is long enough or fill specific index
        while(updatedGrades.length <= testIndex) updatedGrades.push(0);

        updatedGrades[testIndex] = update.grade;

        const average = updatedGrades.reduce((a, b) => a + b, 0) / updatedGrades.length;
        let status: 'Pass' | 'Fail' | 'Warning' = 'Pass';
        if (average < 8) status = 'Fail';
        else if (average < 10) status = 'Warning';

        return { ...s, grades: updatedGrades, status };
      }
      return s;
    }));
    if (aiAnalysis) setAiAnalysis(null);
  };

  const handleSaveRules = (newRules: ObservationRule[]) => {
    setObservationRules(newRules);
    setIsRulesModalOpen(false);
  };

  const sortedClasses = [...classes].sort((a, b) => {
    if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
    if (a.isFavorite !== b.isFavorite) return a.isFavorite ? -1 : 1;
    return parseInt(a.id) - parseInt(b.id);
  });

  return (
    <div className={`flex min-h-screen bg-slate-50/50 ${isAr ? 'flex-row-reverse' : ''}`} dir={isAr ? 'rtl' : 'ltr'}>
      <input 
        type="file" 
        className="hidden" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".xlsx,.xls"
      />

      {isImporting && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center">
          <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 max-w-sm w-full">
            <div className="p-4 bg-blue-50 rounded-full">
              <Loader2 className="animate-spin text-blue-600" size={32} />
            </div>
            <div className="text-center">
              <h3 className="text-xl font-bold text-slate-800">Importation en cours...</h3>
              <p className="text-slate-500 text-sm mt-1">Traitement de votre fichier Excel Massar</p>
            </div>
          </div>
        </div>
      )}

      {isAddNoteModalOpen && (
        <AddNoteModal 
          students={students} 
          t={t} 
          lang={lang} 
          onClose={() => setIsAddNoteModalOpen(false)}
          onSave={handleSaveGradeFromModal}
        />
      )}

      {isVoiceModalOpen && (
        <VoiceEntryModal
          students={students}
          t={t}
          lang={lang}
          onClose={() => setIsVoiceModalOpen(false)}
          onSave={handleBatchUpdateFromVoice}
        />
      )}

      {isRulesModalOpen && (
        <ObservationRulesModal 
          rules={observationRules}
          lang={lang}
          onClose={() => setIsRulesModalOpen(false)}
          onSave={handleSaveRules}
        />
      )}

      <Sidebar 
        lang={lang} 
        t={t} 
        classes={sortedClasses} 
        selectedClassId={selectedClassId} 
        currentView={currentView}
        onSelectClass={(id) => { setSelectedClassId(id); setCurrentView('class'); }}
        onDashboardClick={() => setCurrentView('dashboard')}
        onImportClick={triggerImport}
        onRenameClass={handleRenameClass}
        onTogglePin={handleTogglePin}
        onToggleFavorite={handleToggleFavorite}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="h-16 bg-white border-b border-slate-200 px-4 md:px-8 flex items-center justify-between sticky top-0 z-30">
          <div className="flex items-center gap-4 flex-1">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all"
            >
              <MenuIcon size={24} />
            </button>
            <div className="relative max-w-md w-full hidden sm:block">
              <Search className={`absolute ${isAr ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-slate-400`} size={18} />
              <input 
                type="text" 
                placeholder="Rechercher un élève..." 
                className={`w-full bg-slate-100/80 border-none rounded-2xl py-2 ${isAr ? 'pr-11 pl-4' : 'pl-11 pr-4'} text-sm font-medium focus:ring-2 focus:ring-blue-500/20 outline-none transition-all`} 
              />
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button 
              onClick={toggleLanguage}
              className="flex items-center gap-2 px-3 py-2 hover:bg-slate-100 rounded-xl text-slate-600 transition-all font-bold text-xs uppercase tracking-wider"
            >
              <Languages size={18} className="text-blue-500" />
              <span className="hidden sm:inline">{lang === 'fr' ? 'العربية' : 'Français'}</span>
            </button>
            <div className="w-px h-6 bg-slate-200"></div>
            <button className="relative p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl transition-all group">
              <Bell size={20} />
              <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white group-hover:scale-110 transition-transform"></span>
            </button>
            <div className="flex items-center gap-3 ml-2 pl-2 cursor-pointer group">
              <img 
                src="https://picsum.photos/seed/prof/100" 
                alt="Prof" 
                className="w-8 h-8 md:w-9 md:h-9 rounded-xl ring-2 ring-slate-100 group-hover:ring-blue-100 transition-all"
              />
              <div className="hidden xl:block">
                <p className="text-xs font-bold text-slate-800">Pr. Amrani</p>
                <p className="text-[10px] text-slate-400 font-medium">Mathématiques</p>
              </div>
            </div>
          </div>
        </header>

        {currentView === 'dashboard' ? (
          <DashboardHome 
            t={t}
            lang={lang}
            classes={classes}
            students={students}
          />
        ) : (
          <div className="p-4 md:p-8 space-y-8 max-w-7xl mx-auto w-full animate-in fade-in zoom-in duration-300">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div>
                <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800 tracking-tight">
                  {lang === 'fr' ? `Classe ${currentClass?.name}` : `القسم ${currentClass?.name}`}
                </h2>
                <p className="text-slate-400 mt-2 font-medium text-sm md:text-base">
                  {lang === 'fr' ? 'Saisie multi-tests : visualisez les progrès de vos élèves' : 'تتبع النقاط المتعددة: راقب تقدم تلامذتك'}
                </p>
              </div>
              <div className="flex gap-2 sm:gap-3">
                <button className="flex-1 sm:flex-none px-4 md:px-5 py-2.5 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50 hover:border-slate-300 shadow-sm transition-all">
                  {lang === 'fr' ? 'Exporter' : 'تصدير'}
                </button>

                <button 
                  onClick={() => setIsVoiceModalOpen(true)}
                  className="flex items-center justify-center gap-2 px-4 py-2.5 bg-indigo-50 border border-indigo-100 rounded-xl text-sm font-bold text-indigo-600 hover:bg-indigo-100 shadow-sm transition-all"
                >
                  <Mic size={18} />
                  <span className="hidden sm:inline">{t.voiceEntry}</span>
                </button>

                <button 
                  onClick={() => setIsAddNoteModalOpen(true)}
                  className="flex-1 sm:flex-none px-4 md:px-5 py-2.5 bg-blue-600 rounded-xl text-sm font-bold text-white hover:bg-blue-700 shadow-lg shadow-blue-200 hover:shadow-blue-300 transition-all"
                >
                  {t.addNote}
                </button>
              </div>
            </div>

            <StatsSection t={t} classInfo={currentClass} />

            <div className="space-y-8">
              <div className="w-full">
                <StudentTable 
                  students={students} 
                  t={t} 
                  lang={lang} 
                  onUpdateGrade={handleUpdateGrade}
                  observationRules={observationRules}
                  onOpenRules={() => setIsRulesModalOpen(true)}
                />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 rounded-3xl p-6 md:p-8 text-white shadow-2xl shadow-blue-200/50 relative overflow-hidden group">
                  <div className="absolute -top-12 -right-12 p-12 bg-white/10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-1000"></div>
                  <div className="flex items-center gap-3 mb-6 relative z-10">
                    <div className="bg-white/20 p-3 rounded-xl backdrop-blur-md shadow-inner border border-white/20">
                      <Sparkles size={26} className="text-blue-100" />
                    </div>
                    <h3 className="font-bold text-2xl tracking-tight">{t.aiInsights}</h3>
                  </div>

                  <div className="min-h-[200px] bg-white/10 backdrop-blur-md rounded-2xl p-6 text-[14px] leading-relaxed relative z-10 border border-white/10 shadow-lg flex flex-col">
                    {loadingAi ? (
                      <div className="flex flex-col items-center justify-center flex-1 gap-4">
                        <div className="relative">
                          <Loader2 className="animate-spin text-white/40" size={40} />
                          <Sparkles className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white animate-pulse" size={20} />
                        </div>
                        <p className="animate-pulse font-medium text-blue-100">
                          {lang === 'fr' ? 'Analyse par Gemini en cours...' : 'جاري التحليل من طرف Gemini...'}
                        </p>
                      </div>
                    ) : aiAnalysis ? (
                      <div className="whitespace-pre-line text-blue-50 font-medium">
                        {aiAnalysis}
                      </div>
                    ) : (
                      <div className="flex flex-col items-center justify-center flex-1 text-center py-6">
                        <div className="bg-white/10 p-5 rounded-full mb-4">
                           <Play size={40} className="text-blue-100 ml-1" />
                        </div>
                        <h4 className="font-bold text-white text-xl mb-2">
                          {lang === 'fr' ? "Prêt pour l'analyse" : "جاهز للتحليل"}
                        </h4>
                        <p className="text-blue-100/70 text-sm mb-6 max-w-[300px]">
                          {lang === 'fr' ? "Obtenez des conseils pédagogiques personnalisés basés sur les notes de vos élèves." : "احصل على نصائح تربوية مخصصة بناءً على نتائج تلامذتك."}
                        </p>
                        <button 
                          onClick={() => generateInsights(students)}
                          className="bg-white text-blue-700 px-8 py-3 rounded-2xl font-bold text-base shadow-lg hover:bg-blue-50 transition-all flex items-center gap-3 active:scale-95"
                        >
                          <Sparkles size={20} />
                          {lang === 'fr' ? "Lancer l'analyse" : "ابدأ التحليل"}
                        </button>
                      </div>
                    )}
                  </div>

                  {aiAnalysis && !loadingAi && (
                    <div className="mt-5 flex justify-end relative z-10">
                      <button 
                        onClick={() => generateInsights(students)}
                        className="text-xs font-bold bg-white/20 hover:bg-white/30 px-5 py-2.5 rounded-xl transition-all backdrop-blur-sm border border-white/10"
                      >
                        {lang === 'fr' ? 'Rafraîchir' : 'تحديث'}
