  id: string;
  name: string;
  grades: number[]; // 4 tests: [T1, T2, T3, T4]
  participation: number;
  status: 'Pass' | 'Fail' | 'Warning';
  avatar: string;
}

export interface ObservationRule {
  id: string;
  min: number;
  max: number;
  template: string;
}

export interface SubjectData {
  students: Student[];
  workbook?: any; // XLSX WorkBook object
  fileName?: string;
}

export interface ClassInfo {
  id: string;
  name: string;
  count: number;
  average: number;
  successRate: number;
  subjects: string[]; // List of available subjects
  subjectData: Record<string, SubjectData>; // Data mapping: Subject Name -> Data
  isPinned?: boolean;
  isFavorite?: boolean;
}

export type Language = 'fr' | 'ar';

export interface Translations {
  dashboard: string;
  classes: string;
  upload: string;
  importAction: string;
  studentName: string;
  grade: string;
  status: string;
  classAverage: string;
  successRate: string;
  aiInsights: string;
  dragDrop: string;
