  settings: string;
  logout: string;
  addNote: string;
  addSubject: string; 
  subject: string; 
  selectStudent: string;
  save: string;
  cancel: string;
  gradeValue: string;
  observationRules: string;
  observation: string;
  averageAbbrev: string;
  test: string;
  voiceEntry: string;
  startRecording: string;
  stopRecording: string;
  processing: string;
  voiceInstructions: string;
  confirmGrades: string;
  noMatchFound: string;
  apply: string;
  retry: string;
  hello: string;
  globalEntryRate: string;
  readyClasses: string;
  totalStudents: string;
  testsEntered: string;
  percentageGrades: string;
  recentActivity: string;
