import React, { useState } from 'react';
import { 
  LayoutDashboard, 
  Users, 
  PlusCircle, 
  Settings, 
  LogOut, 
  GraduationCap, 
  FileUp, 
  Pin, 
  Star, 
  Pencil,
  Check,
  X
} from 'lucide-react';
import { Language, Translations, ClassInfo } from '../types';

interface SidebarProps {
  lang: Language;
  t: Translations;
  classes: ClassInfo[];
  selectedClassId: string;
  onSelectClass: (id: string) => void;
  onDashboardClick: () => void;
  onImportClick: () => void;
  onRenameClass: (id: string, newName: string) => void;
  onTogglePin: (id: string) => void;
  onToggleFavorite: (id: string) => void;
  isOpen?: boolean;
  onClose?: () => void;
  currentView?: 'dashboard' | 'class';
}

const Sidebar: React.FC<SidebarProps> = ({ 
  lang, t, classes, selectedClassId, onSelectClass, onDashboardClick, onImportClick,
  onRenameClass, onTogglePin, onToggleFavorite, isOpen, onClose, currentView = 'dashboard'
}) => {
  const isAr = lang === 'ar';
  const [editingId, setEditingId] = useState('')
  const [newClassName, setNewClassName] = useState('')

  const handleRename = (id: string) => {
    setEditingId(id)
    const classToRename = classes.find(c => c.id === id);
    if(classToRename){
        setNewClassName(classToRename.name)
    }
  }

  const handleSaveRename = (id: string) => {
    onRenameClass(id, newClassName)
    setEditingId('')
    setNewClassName('')
  }

  const handleCancelRename = () => {
      setEditingId('')
      setNewClassName('')
  }

  return (
    <div className={`
      bg-white 
      dark:bg-gray-800 
      w-full 
      md:w-64 
      h-full 
      flex 
      flex-col 
      items-center 
      py-4 
      transition-transform 
      duration-300 
      ease-in-out 
      md:translate-x-0
      ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
    `}>
      {/* Logo and App Name */}
      <div className="flex items-center space-x-2 mb-8">
        <GraduationCap size={32} />
        <span className="text-2xl font-bold dark:text-white">EduFlow</span>
      </div>

      {/* Dashboard Button */}
      <button 
